126	  } catch (e) {
127	    if (toError(e).message === 'Resource not accessible by integration') {
128	      logger.warn(
129	        `The GitHub app or token provided may not have the required permissions to create the ${user.data.type} repository ${owner}/${repo}.`,
130	      );
131	    }
132	    throw new Error(
133	      `Failed to create the ${user.data.type} repository ${owner}/${repo}, ${
134	        toError(e).message
135	      }`,
136	    );
137	  }
138	
139	  if (access?.startsWith(`${owner}/`)) {
