/**
 * Determines whether the given error represents a connection-level failure that
 * the GraphQL push fallback should handle.
 */
export function isConnectionResetError(error: unknown): boolean {
  const connectionCodes = ['ECONNRESET', 'ECONNREFUSED'];
  const err = error as { code?: string; cause?: { code?: string } };
  return (
    connectionCodes.includes(err?.code ?? '') ||
    connectionCodes.includes(err?.cause?.code ?? '')
  );
}

function getErrorStatus(error: unknown): number | undefined {
  const err = error as { status?: number; response?: { status?: number } };
  return err?.status ?? err?.response?.status;
}

/**
 * Recursively collects the files within the given directory as GraphQL commit
 * additions, encoding the contents as base64. The '.git' directory, symbolic
 * links, and any entries that are neither regular files nor directories are
 * skipped.
 */
function collectFileAdditions(
  rootDir: string,
): { path: string; contents: string }[] {
  const additions: { path: string; contents: string }[] = [];

  if (!fs.existsSync(rootDir)) {
    return additions;
  }

  const walk = (currentDir: string) => {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true });
    for (const entry of entries) {
      // Skip symbolic links entirely
      if (entry.isSymbolicLink()) {
        continue;
      }

      const fullPath = path.join(currentDir, entry.name);

      if (entry.isDirectory()) {
        // Never traverse into the .git directory
        if (entry.name === '.git') {
          continue;
        }
        walk(fullPath);
      } else if (entry.isFile()) {
        const relativePath = path
          .relative(rootDir, fullPath)
          .split(path.sep)
          .join('/');
        additions.push({
          path: relativePath,
          contents: fs.readFileSync(fullPath).toString('base64'),
